INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.76.1',
  '2026-08-07',
  'Пульт ТВ: музыка в своём плеере, код на виду, «во весь экран»',
  E'Три исправления по итогам живой проверки.\n\nМузыка открывалась в видеоплеере — чёрный прямоугольник вместо трека. Пульт всегда просил «играть как видео», не глядя на содержимое файла. Теперь решает сам файл: без видеодорожки он уходит в музыкальный плеер. В списке на пульте видно, что есть что: 🎬 у видео, 🎵 у музыки. Очередь тоже стала однородной — за серией не начнётся трек, даже если они лежат в одной папке. Кнопка 🎵 у фильма осталась: ей его можно пустить фоном как звук.\n\nКод для пульта теперь виден и после входа — строкой рядом с навигацией, а не только на экране запуска. Подключить второй телефон можно во время просмотра.\n\nКнопка «во весь экран» не работала: в браузере приставки родной полноэкранный режим не отрабатывает, а команда с телефона для него и не жест на телевизоре. Сделали своими силами на CSS — видео разворачивается на весь экран, остальное прячется.',
  E'Куда играть, решает содержимое, а не пожелание пульта: файл без видеодорожки в <video> — это чёрный прямоугольник вместо музыки. Логика собрана в одну функцию startFrom(), общую для локального списка на приставке и для команд с пульта, чтобы два пути не разъезжались.\n\nОчередь однородная: при выборе серии в неё попадают только файлы с картинкой, при выборе трека — только без неё. as:"music" оставлен как явное пожелание пустить фильм фоном.\n\nПолный экран — свой режим на CSS (класс theater): Fullscreen API в вебвью приставки не отрабатывает, а команда с пульта приходит без пользовательского жеста на самом телевизоре, когда браузер его и не разрешил бы. Родной режим пробуем следом, необязательным бонусом.\n\nПоймано при проверке: getComputedStyle возвращает ЖИВОЙ объект, и первый замер «во весь экран» показал position:static — потому что строка читалась уже после обратного переключения. Замер переписан на снятие значения сразу; настоящий результат — fixed во весь размер окна.\n\nПроверено на настоящих библиотеках пользователя: 7 проверок, включая 99 треков в музыкальной очереди, 8 файлов с картинкой в видеоочереди и то, что запуск серии не сбивает играющую музыку.'
);
-- +goose StatementEnd

